  20% { stroke-dasharray: 120, 296; stroke-dashoffset: 60; }
  40% { stroke-dasharray: 296, 50; stroke-dashoffset: 0px; animation-timing-function: ease-in; }
  60% { stroke-dasharray: 200, 100; stroke-dashoffset: -100; }
  80% { stroke-dasharray: 100, 296; stroke-dashoffset: -200; }
  100% { stroke-dasharray: 90, 296; stroke-dashoffset: -296; }
}
@keyframes rotate { 
  100% { transform: rotate(360deg); }
}
@media screen and (forced-colors: active), (-ms-high-contrast:active) {
  .ODSLoadingSpinner .ODSLoadingSpinner-Container { stroke: none; }
}
@media (forced-colors: active) {
  .ODSLoadingSpinner.ODSLoadingSpinner--variant-white .ODSLoadingSpinner-ProgressIndicator, .ODSLoadingSpinner.ODSLoadingSpinner--variant-black .ODSLoadingSpinner-ProgressIndicator { stroke: currentcolor; }
}

